export {
  itemView,
  menuView,
  popupView,
  rootView,
  separatorView,
  triggerView,
} from "../menubar";
export type {
  ItemViewConfig,
  MenubarStyle,
  MenuViewConfig,
  PopupViewConfig,
  RootViewConfig,
  TriggerViewConfig,
} from "../menubar";

export {
  shadcnMenubarItemClassName,
  shadcnMenubarMenuClassName,
  shadcnMenubarPopupClassName,
  shadcnMenubarRootClassName,
  shadcnMenubarSeparatorClassName,
  shadcnMenubarTriggerClassName,
} from "./view";

export {
  menubarItemClassName as shadcnMenubarItemClassName,
  menubarMenuClassName as shadcnMenubarMenuClassName,
  menubarPopupClassName as shadcnMenubarPopupClassName,
  menubarRootClassName as shadcnMenubarRootClassName,
  menubarSeparatorClassName as shadcnMenubarSeparatorClassName,
  menubarTriggerClassName as shadcnMenubarTriggerClassName,
} from "../menubar/view";

import { describe, expect, test } from "vitest";

import * as Menubar from "./index";

describe("shadcn Menubar registry view", () => {
  test("reuses the Foldkit Menubar view contract", () => {
    expect(Menubar.rootView).toBeTypeOf("function");
    expect(Menubar.triggerView).toBeTypeOf("function");
    expect(Menubar.popupView).toBeTypeOf("function");
    expect(Menubar.shadcnMenubarRootClassName).toContain("border");
  });
});
